/bin/bash -lc "python3 -m py_compile /workspace/openai_client.py && python3 - <<'PY'
import json
import openai_client

class Response:
    def __enter__(self): return self
    def __exit__(self, *args): pass
    def read(self):
        return json.dumps({\"output\": [{\"type\": \"message\", \"content\": [{\"type\": \"output_text\", \"text\": \"ok\"}]}]}).encode()

seen = {}
def fake_urlopen(request, timeout, context):
    seen.update(url=request.full_url, body=json.loads(request.data), auth=request.headers[\"Authorization\"])
    return Response()

openai_client.urllib.request.urlopen = fake_urlopen
assert openai_client.send_prompt(\"private\", api_key=\"test-key\") == \"ok\"
assert seen[\"body\"][\"store\"] is False
assert seen[\"body\"][\"input\"] == \"private\"
assert seen[\"auth\"] == \"Bearer test-key\"
print(\"syntax/import/mock request: ok\")
PY"

